    int max = 0;
    int ans = 0;
    for(int i = 0; i<nums.length; i++){
        max = Math.max(max,nums[i]);
    }
    int low = 1; 
    int high = max;
    while( low <= high){
        int mid = low + (high - low)/2;
        long hours = calculateHours(nums,mid);
        if(hours <= h ){
            ans = mid;
            high = mid - 1;
        }
        else{
            low = mid + 1;
        }
