    public long calculateHours(int[] nums, int bananas){
        long count = 0;
        for(int i = 0; i<nums.length; i++){
            if(nums[i]%bananas==0){
                count += nums[i] / bananas;
            }
            else{
                count += nums[i]/bananas +1;
            }
        }
        return count;
    }
}
