class Solution {
    // Function to find minimum eating speed
    public int minimumRateToEatBananas(int[] piles, int h) {
        int maxPile = Arrays.stream(piles).max().getAsInt();
        int low = 1, high = maxPile;
        int ans = maxPile;

        // Binary search on answer space
        while (low <= high) {
            int mid = (low + high) / 2;

            // If possible, try smaller speed
            if (isTotalHoursValid(piles, mid, h)) {
                ans = mid;
                high = mid - 1;
            }
            // Otherwise, try larger speed
            else {
                low = mid + 1;
            }
        }
        return ans;
    }

    // Function to calculate total hours at given speed
    private boolean isTotalHoursValid(int[] piles, int speed, int h) {
        long totalH = 0;
        for (int bananas : piles) {
            totalH += bananas / speed;
            if(bananas % speed != 0) totalH++;
        }
        return totalH <= h;
    }
}
```

